#!/usr/bin/env python3

"""
========================================================
RoboMaster 哨兵机器人
第17课：激光雷达区域划分
========================================================

上一课：

    /scan
      ↓
    找到最近障碍物
      ↓
    距离 + 方向


这一课：

    /scan
      ↓
    按角度划分区域
      ↓
    前方
    左方
    右方
    后方
      ↓
    分别寻找每个区域的最近障碍物


最终得到：

    前方最近距离
    左方最近距离
    右方最近距离
    后方最近距离


以后决策系统可以使用这些数据：

    前方太近？
        ↓
    左边安全？
        ↓
    右边安全？
        ↓
    选择运动方向

========================================================
"""

# ========================================================
# 1. 导入 ROS2
# ========================================================

import rclpy

from rclpy.node import Node


# ========================================================
# 2. 导入 LaserScan
# ========================================================

from sensor_msgs.msg import LaserScan


# ========================================================
# 3. 导入数学库
# ========================================================

import math


# ========================================================
# 4. 创建节点
# ========================================================

class ScanZone(Node):

    def __init__(self):

        # 创建 ROS2 节点

        super().__init__(
            "lesson17_scan_zone"
        )


        # =================================================
        # 创建 Subscriber
        # =================================================

        self.subscription = self.create_subscription(

            LaserScan,

            "/scan",

            self.scan_callback,

            10
        )


        # =================================================
        # 输出提示
        # =================================================

        self.get_logger().info(

            "第17课：正在等待 /scan 数据..."
        )


    # ====================================================
    # /scan 回调函数
    # ====================================================

    def scan_callback(self, scan):

        """
        每收到一帧雷达数据，就执行一次。

        本函数负责：

            1. 遍历所有雷达数据
            2. 计算每个数据对应的角度
            3. 判断属于哪个区域
            4. 保存该区域最近距离
        """


        # =================================================
        # 初始化四个方向的最近距离
        # =================================================

        front_distance = float("inf")

        left_distance = float("inf")

        right_distance = float("inf")

        back_distance = float("inf")


        # =================================================
        # 遍历所有雷达数据
        # =================================================

        for i, distance in enumerate(scan.ranges):


            # ------------------------------------------------
            # 过滤无效数据
            # ------------------------------------------------

            if not math.isfinite(distance):

                continue


            # ------------------------------------------------
            # 过滤超出雷达范围的数据
            # ------------------------------------------------

            if distance < scan.range_min:

                continue


            if distance > scan.range_max:

                continue


            # =================================================
            # 计算当前数据对应的角度
            # =================================================

            angle = (

                scan.angle_min

                + i * scan.angle_increment
            )


            # 转换成角度

            angle_degree = math.degrees(angle)


            # =================================================
            # 判断当前数据属于哪个区域
            # =================================================

            # ------------------------------------------------
            # 前方
            # ------------------------------------------------

            # -45° ~ +45°

            if -45.0 <= angle_degree <= 45.0:

                if distance < front_distance:

                    front_distance = distance


            # ------------------------------------------------
            # 左方
            # ------------------------------------------------

            # +45° ~ +135°

            elif 45.0 < angle_degree <= 135.0:

                if distance < left_distance:

                    left_distance = distance


            # ------------------------------------------------
            # 右方
            # ------------------------------------------------

            # -135° ~ -45°

            elif -135.0 <= angle_degree < -45.0:

                if distance < right_distance:

                    right_distance = distance


            # ------------------------------------------------
            # 后方
            # ------------------------------------------------

            else:

                if distance < back_distance:

                    back_distance = distance


        # =================================================
        # 输出结果
        # =================================================

        self.get_logger().info(

            f"前方：{front_distance:.2f} m | "

            f"左方：{left_distance:.2f} m | "

            f"右方：{right_distance:.2f} m | "

            f"后方：{back_distance:.2f} m"
        )


# ========================================================
# main
# ========================================================

def main(args=None):

    # 初始化 ROS2

    rclpy.init(args=args)


    # 创建节点

    node = ScanZone()


    try:

        # 持续运行

        rclpy.spin(node)


    except KeyboardInterrupt:

        pass


    # 销毁节点

    node.destroy_node()


    # 关闭 ROS2

    rclpy.shutdown()


# ========================================================
# 程序入口
# ========================================================

if __name__ == "__main__":

    main()